mapper.delete:
DELETE FROM app_h5_security_event
WHERE id IN (
    SELECT stale.id
    FROM (
        SELECT id
        FROM app_h5_security_event
        WHERE created_at < #{cutoff}
        ORDER BY id
        LIMIT #{limit}
    ) stale
)
